SELECT s.id AS id, s.contract_id AS contractId, c.contract_no AS contractNo, c.contract_name AS contractName, c.business_entity_id AS businessEntityId, be.name AS businessEntityName, s.seal_type AS sealType, s.applied_copies AS appliedCopies, s.actual_copies AS actualCopies, s.applicant_id AS applicantId, s.apply_remark AS applyRemark, s.status AS status, s.approver_id AS approverId, s.approved_at AS approvedAt, s.approve_remark AS approveRemark, s.organization_id AS organizationId, s.create_time AS createTime FROM ad_seal_record s LEFT JOIN ad_contract c ON c.id = s.contract_id AND c.deleted = 0 LEFT JOIN ad_business_entity be ON be.id = c.business_entity_id AND be.deleted = 0 WHERE s.organization_id = #{request.organizationId} AND s.deleted = 0
AND s.contract_id = #{request.contractId}
AND s.seal_type = #{request.sealType}
AND s.status = #{request.status}
AND c.business_entity_id = #{request.businessEntityId}
AND (c.contract_no LIKE CONCAT('%', #{request.keyword}, '%') OR c.contract_name LIKE CONCAT('%', #{request.keyword}, '%'))
AND s.create_time >= #{request.applyDateFrom}
AND s.create_time <= #{request.applyDateTo}
AND c.business_entity_id IN
#{eid}
